const { error } = require('console');
const fs = require('fs-extra');
const path = require('path');

var _robloxPathDict;
var _options;

var isInit = false
var luaSystems = {}
var _systemRoot



function getSystemByFilePath(path) {
    path = path.replace(/\\/g, '/');

    // 获取所有系统路径
    const systems = Object.values(luaSystems).map(system => system);

    // 按长度降序排序，以便优先匹配最长的路径
    systems.sort((a, b) => b.FilePath.length - a.FilePath.length);


    // 遍历所有系统路径
    for (const system of systems) {
        // 检查给定路径是否以系统路径开头
        if (path.startsWith(system.FilePath)) {
            // 返回匹配的系统名称
            return system;
        }
    }

    return null;
}


function getWorkspaceTarget(target) {
    var splits = target.split("@")
    target = splits[splits.length - 1]
    if (target == "server") {
        target = "ServerScriptService"
    }
    return {
        Name: splits[0],
        Target: target
    }
}


function isLocationDefine(filePath) {


    // 检查文件名是否包含@符号
    return filePath.includes('@')
}

function getSystemSubDirNotInRs(filePath) {
    // 遍历 filePath 的所有文件，递归， 如果以@开头，则认为该文件所在的目录需要被忽略
    var ignoreDirs = []


    function readDirRecursively(filePath, files) {
        if (!files) {
            files = []
        }
        const items = fs.readdirSync(filePath, { withFileTypes: true })

        for (const item of items) {
            if (item.isDirectory()) {
                files.push(item)
            }
        }
        for (const item of items) {
            const fullPath = path.join(filePath, item.name)
            if (item.isDirectory()) {
                readDirRecursively(fullPath, files)
            }
        }
        return files
    }

    for (const item of readDirRecursively(filePath)) {
        if (!isLocationDefine(item.name)) {
            continue
        }

        var target = getWorkspaceTarget(item.name)

        ignoreDirs.push({
            Path: path.join(item.path, item.name).replace(/\\/g, '/'),
            Rename: path.join(item.path, target.Name).replace(/\\/g, '/'),
            Target: target.Target
        })
    }
    return ignoreDirs
}


function gen(filePath) {

    var fileFolder = path.dirname(filePath);
    const fileName = path.basename(filePath);
    var root = undefined

    // if file name format as .system.{Root}.* , use regex to get root
    var match = fileName.match(/^\.system\.(.*)\..*$/)
    if (match) {
        root = match[1]
    }

    fileFolder = fileFolder.replace(/\\/g, '/');

    luaSystems[fileFolder] = {
        FilePath: fileFolder,
        Name: path.basename(fileFolder),
        Root: root
    }

    var systemInfo = luaSystems[fileFolder]

    if (fileFolder.startsWith(_systemRoot)) {
        var str = fileFolder.substring(_systemRoot.length).replace(/^\//, '');
        systemInfo.IsInSystemRoot = true
        systemInfo.NodesFromRoot = str.split('/')
    }

    if (isInit) {
        var rbxPath = _robloxPathDict.getRbxPath(fileFolder)
        systemInfo.RbxPath = rbxPath
    }

    var altDirs = getSystemSubDirNotInRs(fileFolder)

    systemInfo.AltDirs = altDirs
}

function isSystemDefineFile(filePath) {

    // get file name
    const fileName = path.basename(filePath);
    if ((fileName.startsWith(".system"))) {
        return true
    }
    return false
}

// 尝试生成路径, 如果有变更, 返回true
function tryGen(filePath) {

    var changed = false

    if (isSystemDefineFile(filePath)) {
        gen(filePath);
        changed = true
    }

    return changed
}

function findAndGenSubfolders(basePath) {

    if (_options.isIgnoreFolder(path.resolve(basePath))) return


    var changed = false
    if (!fs.existsSync(basePath)) {
        if (isSystemDefineFile(basePath)) {
            var rbxPath = _robloxPathDict.getRbxPath(basePath)
            delete luaSystems[rbxPath];
            return true
        }
        return false
    }
    if (fs.lstatSync(basePath).isDirectory()) {

        for (const item of fs.readdirSync(basePath, { withFileTypes: true })) {

            const fullPath = path.join(basePath, item.name);
            changed |= findAndGenSubfolders(fullPath);
        }
    } else {
        changed |= tryGen(basePath)
    }
    return changed
}


function onDelete(filePath) {
    if (isSystemDefineFile(filePath)) {
        var folder = path.dirname(filePath)
        var rbxPath = _robloxPathDict.getRbxPath(folder)

        // 如果目录中仍然有系统定义文件，则不删除
        if (fs.existsSync(folder)) {
            for (const item of fs.readdirSync(folder, { withFileTypes: true })) {
                var fullPath = path.join(folder, item.name);
                if (isSystemDefineFile(fullPath)) {
                    return
                }
            }
        }
        delete luaSystems[rbxPath];
    } else {
        var rbxPath = _robloxPathDict.getRbxPath(filePath)
        for (const key in luaSystems) {
            if (key.startsWith(rbxPath)) {
                delete luaSystems[key];
            }
        }
    }

    if (isSystemDefineFile(filePath)) {
        var rbxPath = _robloxPathDict.getRbxPath(filePath)
        delete luaSystems[rbxPath];
    }
}

function validateSystems() {
    for (const key1 in luaSystems) {
        for (const key2 in luaSystems) {
            if (key1 == key2) {
                continue
            }
            if (key1.length < key2.length && key2.startsWith(key1 + "/")) {
                var fullPath1 = path.resolve(luaSystems[key1].FilePath)
                var fullPath2 = path.resolve(luaSystems[key2].FilePath)

                throw new Error(`系统内不允许设置子系统: \n ${fullPath1} \n ${fullPath2}`)
            }

        }
    }
}

module.exports = {
    Init: function (options) {
        _options = options
        _robloxPathDict = options.robloxPathDict;
        _systemRoot = options.systemRoot
        if (_robloxPathDict) {
            isInit = true
        }
    },

    TryGen: function (paths) {
        var changed = false
        for (const basePath of paths) {
            changed |= findAndGenSubfolders(basePath);
        }
        validateSystems()
        return changed
    },
    TryGenOnUpdate: function (events) {
        var changed = false

        for (var key in events) {
            if (isLocationDefine(key)) {
                // get key's parent's parent
                var parent = path.dirname(path.dirname(key))
                changed |= findAndGenSubfolders(parent)
            } else {
                if (events[key].startsWith("unlink")) {
                    onDelete(key)
                    changed = true
                } else {
                    changed |= findAndGenSubfolders(key)
                }
            }
        }
        validateSystems()
        return changed
    },
    GetSystems: function () {
        return luaSystems
    },
    GetSystemsKeyByPath: function () {
        return luaSystems
    },
    GetSystemByFilePath: getSystemByFilePath

}